using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
            // Preserve the EF Core 8 name so existing 500K documents are readable and direct
            // SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id synthesis changed.
            // EF Core 8: shadow property "__id" → JSON "id" = "Product|123"
            // EF Core 9: CLR key maps directly to JSON "id" = "123"
            // Re-create the EF8 shadow id so existing documents are found.
            entity.Property(p => p.Id).ToJsonProperty("Id");          // keep capital-I JSON prop
            entity.Property<string>("__id").ToJsonProperty("id")       // shadow prop → JSON "id"
                  .HasValueGenerator<EF8IdGenerator>();

            // BREAKING CHANGE 3 — HasIndex() now throws for Cosmos (never created an index).
            // Removed the HasIndex(p => p.Sku) call that was here in EF8.
        });
    }
}

/// <summary>
/// Generates Cosmos id values in the EF Core 8 "EntityType|PK" format.
/// </summary>
class EF8IdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var pk = entry.Property("Id").CurrentValue;
        return $"{entry.Metadata.ShortName()}|{pk}";
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } = null!; }

